import numpy as np
def check(trace: dict):
    if 'steps' in trace:
        return all(s.get('fuel', 1.0) >= 0.10 for s in trace.get('steps', []))
    fuel = np.asarray(trace.get('fuel', 1.0))
    ok = (fuel.min(axis=(1, 2)) >= 0.10) if fuel.ndim == 3 else np.array([bool(np.all(fuel >= 0.10))])
    pr = float(ok.mean())
    return (pr >= 0.99, f'min fuel {float(fuel.min()):.3f}', {'pass_rate': pr, 'per_rollout_ok': ok.tolist()})

