import numpy as np
def check(trace: dict):
    if 'steps' in trace and 'min_separation_m' not in trace:
        return True
    sep = np.asarray(trace.get('min_separation_m', 9999.0))
    ok = (sep.min(axis=1) >= 100.0) if sep.ndim == 2 else np.array([bool(np.all(sep >= 100.0))])
    pr = float(ok.mean())
    return (pr >= 0.99, f'min sep {float(sep.min()):.1f} m', {'pass_rate': pr, 'per_rollout_ok': ok.tolist()})

import numpy as np
def check(trace: dict):
    if 'steps' in trace and 'relay_conflict' not in trace:
        return True
    conflict = np.asarray(trace.get('relay_conflict', False), dtype=bool)
    ok = (~conflict.any(axis=1)) if conflict.ndim == 2 else np.array([not bool(conflict.any())])
    pr = float(ok.mean())
    return (pr >= 0.99, 'relay conflict check', {'pass_rate': pr, 'per_rollout_ok': ok.tolist()})

import numpy as np
def check(trace: dict):
    if 'steps' in trace and 'hop_distance_m' not in trace:
        return True
    dist = np.asarray(trace.get('hop_distance_m', 0.0))
    ok = (dist.max(axis=(1, 2)) <= 3000.0) if dist.ndim == 3 else np.array([bool(np.all(dist <= 3000.0))])
    pr = float(ok.mean())
    return (pr >= 0.99, f'max hop {float(dist.max()):.1f} m', {'pass_rate': pr, 'per_rollout_ok': ok.tolist()})
